    knobs: { d: "M8.75 3v3M5.75 10v3" },
  },
  help: {
    ring: { d: RING },
    hook: { d: "M6.25 6.4a1.8 1.8 0 1 1 2.55 1.65c-.5.25-.8.6-.8 1.1v.25" },
