    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* 50, like the popovers: one opened inside the drawer portals later, so it stacks above. */
  .viewport {
    position: fixed;
    z-index: 50;
    inset: 0;
    pointer-events: none;
  }

  /* The scrim is a sibling, not ::backdrop any more, so it gets the timings too. */
  .backdrop,
  .drawer {
    --drawer-open: 420ms;
    --drawer-close: 280ms;
  }

  .drawer {
    --drawer-pad: var(--ui-space-5);
    --drawer-width: 420px;
    --drawer-safe: env(safe-area-inset-bottom, 0px);
    position: fixed;
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    border: 0;
    background: var(--ui-surface);
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
    /* Visible so the sheet's ::after strip shows when pulled up; .frame clips instead. */
    overflow: visible;
    overscroll-behavior: contain;
    outline: none;
    pointer-events: auto;
    /* Base UI sets the swipe offsets while a finger drags the sheet. */
    transform: translate3d(var(--drawer-swipe-movement-x, 0px), var(--drawer-swipe-movement-y, 0px), 0);
    transition: transform var(--drawer-open) var(--ui-ease-expand);
  }

  /* Released short of dismissing: glide back. */
  .drawer[data-settled] {
    transition: transform var(--ui-dur-glide) var(--ui-ease-glide);
  }

  .drawer[data-swiping] {
    user-select: none;
    transition-duration: 0ms;
  }

  /* Off screen, clear of the shadow, so nothing of the panel shows. */
  .drawer[data-starting-style],
  .drawer[data-ending-style] {
    transform: translate3d(0, calc(100% + 24px), 0);
  }

  /* Keyed to data-from, which the component renders with the panel: Base
     UI's data-swipe-direction arrives a frame later, so on the first open
     the panel used to start from the wrong side and land almost at once. */
  .drawer[data-mode="side"][data-from="right"]:is([data-starting-style], [data-ending-style]) {
    transform: translate3d(calc(100% + 24px), 0, 0);
  }

  .drawer[data-mode="side"][data-from="left"]:is([data-starting-style], [data-ending-style]) {
    transform: translate3d(calc(-100% - 24px), 0, 0);
  }

  /* A flick hands over its speed: the faster the release, the shorter the exit. */
  .drawer[data-ending-style] {
    transition: transform calc(var(--drawer-close) * var(--drawer-swipe-strength, 1)) var(--ui-ease-expand);
  }

  .drawer[data-size="sm"] {
    --drawer-width: 360px;
  }

  .drawer[data-size="lg"] {
    --drawer-width: 560px;
  }

  .drawer[data-mode="side"] {
    inset-block: 0;
    inset-inline: auto 0;
    width: var(--drawer-width);
    max-width: calc(100% - var(--ui-space-7));
    height: 100dvh;
    max-height: none;
    /* The floating shadow carries the edge, on the open side too. */
    box-shadow: var(--ui-shadow-floating);
  }

  .drawer[data-mode="side"][data-side="start"] {
    inset-inline: 0 auto;
  }

  .drawer[data-mode="sheet"] {
    inset-inline: 0;
    inset-block: auto var(--drawer-keyboard, 0px);
    width: 100%;
    max-width: 640px;
    height: auto;
    max-height: calc(100dvh - var(--drawer-keyboard, 0px) - var(--ui-space-7));
    margin-inline: auto;
    border-start-start-radius: var(--ui-radius-lg);
    border-start-end-radius: var(--ui-radius-lg);
    /* The floating shadow carries the edge: one ring, so the top line is the
       same weight as every other box's. */
    box-shadow: var(--ui-shadow-floating);
  }

  .drawer[data-mode="sheet"][data-keyboard] {
    --drawer-safe: 0px;
  }

  .drawer[data-mode="sheet"]::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    top: 100%;
    height: var(--ui-space-8);
    background: var(--ui-surface);
  }

  /* ---------- Scrim ---------- */

  .backdrop {
    position: fixed;
    z-index: 50;
    inset: 0;
    min-height: 100dvh;
    background: var(--ui-scrim);
    opacity: calc(1 - var(--drawer-swipe-progress, 0));
    transition: opacity var(--drawer-open) var(--ui-ease-expand);
  }

  .backdrop[data-starting-style],
  .backdrop[data-ending-style] {
    opacity: 0;
  }

  .backdrop[data-swiping] {
    transition-duration: 0ms;
  }

  .backdrop[data-ending-style] {
    transition-duration: calc(var(--drawer-close) * var(--drawer-swipe-strength, 1));
  }

  @media (prefers-reduced-motion: reduce) {
    .backdrop,
    .backdrop[data-ending-style] {
      transition-duration: var(--ui-dur-instant);
    }
    .drawer,
    .drawer[data-settled],
    .drawer[data-ending-style] {
      transition: opacity var(--ui-dur-instant) var(--ui-ease-enter);
    }
    .drawer[data-starting-style],
    .drawer[data-ending-style],
    .drawer[data-mode="side"]:is([data-starting-style], [data-ending-style]) {
      transform: none;
      opacity: 0;
    }
  }

  /* ---------- Layout ---------- */

  .frame {
    display: grid;
    /* Named rows, so an absent handle, body or footer doesn't shift the others. */
    grid-template-rows: [handle] auto [header] auto [body] minmax(0, 1fr) [footer] auto;
    height: 100%;
    max-height: inherit;
    border-radius: inherit;
    overflow: clip;
  }

  .drawer[data-mode="sheet"] .frame {
    height: auto;
  }

  .handle {
    display: none;
  }

  .drawer[data-mode="sheet"] .handle {
    display: block;
    grid-row: handle;
    justify-self: center;
    width: var(--ui-space-6);
    height: var(--ui-space-1);
    margin-block-start: var(--ui-space-2);
    border-radius: var(--ui-radius-full);
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
  }

  .header {
    grid-row: header;
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    padding: var(--drawer-pad) var(--drawer-pad) var(--ui-space-4);
  }

  .drawer[data-mode="sheet"] .header {
    padding-block-start: var(--ui-space-3);
  }

  .drawer[data-mode="sheet"] :is(.handle, .header, .footer) {
    touch-action: none;
  }

  .heading {
    display: grid;
    flex: 1;
    gap: var(--ui-space-1);
    min-width: 0;
    padding-top: var(--ui-space-1);
  }

  .title {
    margin: 0;
    color: var(--ui-foreground);
    font-family: var(--ui-font-display);
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-2xl);
    letter-spacing: var(--ui-tracking-heading);
    text-wrap: balance;
  }

  .description {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .close {
    --close-size: var(--ui-control-sm);
    display: grid;
    place-items: center;
    flex-shrink: 0;
    --close-width: calc(var(--close-size) * var(--ui-capsule));
    width: var(--close-width);
    height: var(--close-size);
    margin-block-start: calc(var(--ui-space-1) + var(--ui-leading-2xl) / 2 - var(--close-size) / 2);
    margin-inline-end: calc((16px - var(--close-width)) / 2);
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .close svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    stroke-width: var(--ui-icon-stroke-medium);
    pointer-events: none;
  }

  @media (hover: hover) {
    .close:hover {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .close:active {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .close:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .close {
      --close-size: var(--ui-control-md);
    }
  }

  .body {
    grid-row: body;
    min-height: 0;
    padding: var(--ui-space-1) var(--drawer-pad) var(--drawer-pad);
    overflow-y: auto;
    overscroll-behavior: contain;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .drawer[data-mode="sheet"] .body:last-child {
    padding-block-end: calc(var(--drawer-pad) + var(--drawer-safe));
  }

  .footer {
    grid-row: footer;
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ui-space-2) var(--ui-space-3);
    padding: var(--ui-space-4) var(--drawer-pad);
  }

  .drawer[data-mode="sheet"] .footer {
    padding-block-end: max(var(--ui-space-4), var(--drawer-safe));
  }

  .header + .footer {
    padding-block-start: var(--ui-space-2);
  }

  .header::after,
  .footer::before {
    content: "";
    position: absolute;
    inset-inline: 0;
    height: var(--ui-hairline);
    background: var(--ui-border);
    pointer-events: none;
  }

  .header::after {
    bottom: 0;
    opacity: 0;
  }

  .footer::before {
    top: 0;
  }

  .header + .footer::before {
    content: none;
  }

  @supports (timeline-scope: --a) {
    .frame {
      timeline-scope: --drawer-scroll;
    }

    .body {
      scroll-timeline: --drawer-scroll block;
    }

    .header::after {
      animation: drawer-edge-in linear both;
      animation-timeline: --drawer-scroll;
      animation-range: 0 var(--ui-space-4);
    }

    .footer::before {
      animation: drawer-edge-out linear both;
      animation-timeline: --drawer-scroll;
      animation-range: calc(100% - var(--ui-space-4)) 100%;
    }
  }

  /* Chromium keeps an animation's last value once its scroll timeline goes inactive,
     so a body that now fits would keep stale edges. The script sets data-fits. */
  .frame:has(> .body[data-fits]) .header::after,
  .frame:has(> .body[data-fits]) .footer::before {
    animation: none;
  }

  @keyframes drawer-edge-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes drawer-edge-out {
    from {
      opacity: 1;
    }
    to {
      opacity: 0;
    }
  }

  .actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--ui-space-2);
    margin-inline-start: auto;
  }

  .drawer[data-mode="sheet"] .actions {
    flex: 1 1 100%;
  }

  .drawer[data-mode="sheet"] .actions > * {
    flex: 1 1 0;
  }

  @media (prefers-reduced-motion: reduce) {
    .close:active {
      scale: none;
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type ReactNode,
  type RefObject,
} from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";
import { Icon } from "../icons/icons";
import styles from "./drawer.module.css";

const FOCUSABLE = [
  "[autofocus]",
  "input:not([type=hidden]):not(:disabled)",
  "select:not(:disabled)",
  "textarea:not(:disabled)",
  "button:not(:disabled)",
  "a[href]",
  "[contenteditable=true]",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

function firstFocusable(root: Element | null) {
  if (!root) return null;
  const autofocus = root.querySelector<HTMLElement>("[autofocus]");
  if (autofocus) return autofocus;
  for (const el of root.querySelectorAll<HTMLElement>(FOCUSABLE)) {
    if (!el.closest("[inert]") && el.getClientRects().length) return el;
  }
  return null;
}

const TEXT_ENTRY = /^(text|search|email|url|tel|password|number|date|time|datetime-local|month|week)$/;

function isTextEntry(el: HTMLElement) {
  if (el instanceof HTMLTextAreaElement || el.isContentEditable) return true;
  return el instanceof HTMLInputElement && TEXT_ENTRY.test(el.type);
}

/** The nearest themed subtree, so the portaled panel keeps its tokens. */
function themeRoot(el: Element | null) {
  const root = el?.closest<HTMLElement>("[data-theme]");
  return root && root !== document.documentElement ? root : undefined;
}

/** Media query under which the drawer becomes a bottom sheet. */
export const SHEET_QUERY = "(max-width: 640px), (pointer: coarse) and (max-height: 500px)";

function subscribe(onChange: () => void) {
  const query = matchMedia(SHEET_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

function useSheetQuery() {
  return useSyncExternalStore(
    subscribe,
    () => matchMedia(SHEET_QUERY).matches,
    () => false,
  );
}

export type DrawerProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  footer?: ReactNode;
  /** Logical edge on wider screens; `bottom` makes it a sheet everywhere. */
  side?: "end" | "start" | "bottom";
  size?: "sm" | "md" | "lg";
  /** Focus target on open. Defaults to the first control in the body. */
  initialFocus?: RefObject<HTMLElement | null>;
  /** Focus returns here on close. Defaults to the element focused at open. */
  triggerRef?: RefObject<HTMLElement | null>;
  /** Focus target on close when the trigger is gone. */
  finalFocus?: RefObject<HTMLElement | null>;
  /** Blocks every way of dismissing, e.g. while saving. */
  locked?: boolean;
  className?: string;
};

/** A modal panel from the screen edge; a draggable bottom sheet on phones. Built on Base UI's Drawer. */
export function Drawer({
  open,
  onOpenChange,
  title,
  description,
  children,
  footer,
  side = "end",
  size = "md",
  initialFocus,
  triggerRef,
  finalFocus,
  locked = false,
  className,
}: DrawerProps) {
  const narrow = useSheetQuery();
  const sheet = side === "bottom" || narrow;

  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const [body, setBody] = useState<HTMLDivElement | null>(null);
  const [footerEl, setFooterEl] = useState<HTMLDivElement | null>(null);
  // Set once the entrance has finished, so a drag released short of dismissing glides back.
  const [settled, setSettled] = useState(false);
  const [rtl, setRtl] = useState(false);

  // The element that opened it, read as `open` turns true, before Base UI
  // mounts the panel and moves focus inside.
  const [trigger, setTrigger] = useState<HTMLElement | null>(null);
  useLayoutEffect(() => {
    if (!open) return;
    const active = document.activeElement;
    const from = triggerRef?.current ?? (active instanceof HTMLElement && active !== document.body ? active : null);
    setTrigger(from);
    setRtl(getComputedStyle(from ?? document.documentElement).direction === "rtl");
  }, [open, triggerRef]);

  const swipeDirection = sheet ? "down" : (side === "start") === rtl ? "right" : "left";

  // Mobile keyboards cover the page without resizing it; lift the sheet by the
  // covered height. Pinch zoom also shrinks the visual viewport, so ignore it.
  useEffect(() => {
    const viewport = window.visualViewport;
    if (!open || !sheet || !popup || !viewport) return;
    function update() {
      const covered = viewport!.scale > 1.01 ? 0 : window.innerHeight - viewport!.height - viewport!.offsetTop;
      if (covered > 1) {
        popup!.style.setProperty("--drawer-keyboard", `${Math.round(covered)}px`);
        popup!.setAttribute("data-keyboard", "");
      } else {
        popup!.style.removeProperty("--drawer-keyboard");
        popup!.removeAttribute("data-keyboard");
      }
    }
    update();
    viewport.addEventListener("resize", update);
    viewport.addEventListener("scroll", update);
    return () => {
      viewport.removeEventListener("resize", update);
      viewport.removeEventListener("scroll", update);
      popup.style.removeProperty("--drawer-keyboard");
      popup.removeAttribute("data-keyboard");
    };
  }, [open, sheet, popup]);

  // data-fits works around a Chromium scroll-timeline bug (see the CSS).
  const markFits = useCallback((el: HTMLDivElement | null) => {
    el?.toggleAttribute("data-fits", el.scrollHeight <= el.clientHeight);
  }, []);
  useEffect(() => {
    if (!body) return;
    markFits(body);
    const observer = new ResizeObserver(() => markFits(body));
    observer.observe(body);
    return () => observer.disconnect();
  }, [body, markFits]);

  function dismiss() {
    if (locked) return;
    onOpenChange(false);
  }

  return (
    <BaseDrawer.Root
      open={open}
      onOpenChange={(next) => {
        // Controlled: `locked` (or the owner) can keep it open.
        if (!next) dismiss();
      }}
      onOpenChangeComplete={(isOpen) => setSettled(isOpen)}
      swipeDirection={swipeDirection}
    >
      <BaseDrawer.Portal container={themeRoot(trigger)}>
        <BaseDrawer.Backdrop className={styles.backdrop} />
        <BaseDrawer.Viewport className={styles.viewport}>
          <BaseDrawer.Popup
            ref={setPopup}
            className={className ? `${styles.drawer} ${className}` : styles.drawer}
            data-mode={sheet ? "sheet" : "side"}
            data-side={side === "start" ? "start" : "end"}
            data-from={sheet ? "bottom" : swipeDirection === "right" ? "right" : "left"}
            data-size={size}
            data-settled={settled || undefined}
            initialFocus={() => {
              let el = initialFocus?.current ?? firstFocusable(body) ?? firstFocusable(footerEl);
              // Focusing a field while the sheet rises throws the keyboard over it.
              if (!initialFocus?.current && sheet && el && isTextEntry(el)) el = null;
              return el ?? popup ?? true;
            }}
            finalFocus={() => {
              if (trigger?.isConnected) return trigger;
              return finalFocus?.current ?? true;
            }}
          >
            {/* Side panels and a locked drawer don't swipe; a sheet does. */}
            <div className={styles.frame} data-base-ui-swipe-ignore={!sheet || locked ? "" : undefined}>
              <div className={styles.handle} aria-hidden="true" />
              <header className={styles.header}>
                <div className={styles.heading}>
                  <BaseDrawer.Title className={styles.title}>{title}</BaseDrawer.Title>
                  {description && (
                    <BaseDrawer.Description className={styles.description}>{description}</BaseDrawer.Description>
                  )}
                </div>
                <BaseDrawer.Close className={styles.close} aria-label="Close">
                  <Icon name="close" />
                </BaseDrawer.Close>
              </header>

              {/* Content: a mouse drag here selects text instead of moving the sheet. */}
              {children && (
                <BaseDrawer.Content
                  ref={setBody}
                  className={styles.body}
                  onScroll={(e) => markFits(e.currentTarget)}
                >
                  {children}
                </BaseDrawer.Content>
              )}

              {footer && (
                <div ref={setFooterEl} className={styles.footer}>
                  {footer}
                </div>
              )}
            </div>
          </BaseDrawer.Popup>
        </BaseDrawer.Viewport>
      </BaseDrawer.Portal>
    </BaseDrawer.Root>
  );
}

/** Footer button row; on a sheet the buttons share the width. */
export function DrawerActions({ children }: { children: ReactNode }) {
  return <div className={styles.actions}>{children}</div>;
}
